Frontend Container.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(frontend_container, "Frontend Container") {
    Component(AuthSessionManager, "Authentication & Session Manager", "TypeScript, React", "Manages multi-factor authentication, OIDC/OAuth2 sessions, and user login state.")
    Component(RoleBasedRouter, "Role-Based Router & Shell", "TypeScript, React", "Controls navigation and UI shells based on user personas and authorization.")
    Component(ClinicalEMRViewComponent, "Clinical EMR View Component", "TypeScript, React", "Renders electronic medical records and interacts with local persistence.")
    Component(APIClientLayer, "API Client Layer", "TypeScript, Fetch / Axios", "Handles outbound HTTPS/JSON requests to the Edge Container.")
    Component(LocalPersistenceManager, "Local Persistence Manager", "IndexedDB", "Reads and writes encrypted drafts and offline data securely.")
    Component(CryptographicVaultManager, "Cryptographic Vault Manager", "Web Crypto API", "Provides client-side encryption and security operations.")
}

Rel(ClinicalEMRViewComponent, LocalPersistenceManager, "Reads/Writes encrypted drafts", "IndexedDB / Web Crypto API")

@enduml

Scheduling Service.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary("Scheduling_Service", "Scheduling Service") {
    Component("API_Router_Component", "API Router Component", "Express.js / Fastify", "Routes requests and handles initial entry into the Scheduling Service.")
    Component("Booking_Engine_Component", "Booking Engine Component", "Node.js / TypeScript", "Manages patient and resource bookings with real-time conflict prevention.")
    Component("Availability_Cache_Component", "Availability Cache Component", "Redis Cluster", "Acquires distributed locks and checks availability using Redlock.")
    Component("Notification_Dispatcher_Component", "Notification Dispatcher Component", "Node.js", "Publishes domain events to the event bus for notifications and analytics.")
}

Rel("API_Router_Component", "Booking_Engine_Component", "Delegates requests", "In-process TypeScript interfaces")
Rel("Booking_Engine_Component", "Availability_Cache_Component", "Acquires distributed locks and checks availability", "TCP with TLS, rediss://")

@enduml

Integration Service / FHIR Facade.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

title Component diagram for the Integration Service / FHIR Facade container

Container_Boundary("integration_service_fhir_facade", "Integration Service / FHIR Facade") {
    Component(gateway, "FHIR API Gateway / Router", "Go using Gin or Fiber", "Routes incoming API requests and handles protocol translation.")
    Component(mapper, "Resource Mapper & Validator", "Go using go-fhir models", "Maps and validates clinical resources against FHIR standards.")
    Component(client_pool, "Outbound/Inbound Client Pool", "Go HTTP/gRPC Client", "Manages client connections for external communication.")
    Component(dlq_handler, "DLQ Management Handler", "Go background worker", "Handles dead-letter queue management and message reprocessing.")
}

Rel(gateway, mapper, "Internal function calls", "Go structs")
Rel(mapper, dlq_handler, "Routes failed payloads", "Async")

@enduml

Event Bus.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(event_bus, "Event Bus") {
    Component(kafka_broker_cluster, "Kafka Broker Cluster", "Apache Kafka (KRaft Mode)", "Publishes and consumes domain events using Kafka Wire Protocol for asynchronous messaging.")
    Component(schema_registry, "Schema Registry", "Avro", "Validates event schemas for microservices.")
    Component(kafka_connect, "Kafka Connect", "Debezium", "Handles change data capture (CDC) and reliable asynchronous messaging.")
    Component(dlq_retry_router, "DLQ & Retry Router", "Kafka Wire Protocol", "Forwards unprocessable events from the Kafka Broker Cluster.")
    Component(event_governance, "Event Governance & Access Control Layer", "Apache Ranger / mTLS", "Authenticates and authorizes operations for microservices interacting with the event bus.")
}

Rel(kafka_broker_cluster, dlq_retry_router, "Forwards unprocessable events", "Kafka Wire Protocol")

@enduml
